From OSSVerify.Proofs.spirv_tools.spvtools_binary_parser_fuzzer.lib Require Import RunRandom.
#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.
Import ListNotations.
Open Scope Z_scope.
Import SymExec3.SX2. Import SymExec3Sound.SX2S.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Module Ly := S1Layout.
Abbreviation SEGS := Plain.M.loaded_segments.

Definition PC_RET_FW1 : Z := 0xd6ad8.

Section Pass2.
  Context {fx : FPState}.
Context {RRND : RunRandom}.
  Variables (R : bvmap 5 word) (M : mem) (sp ret v conv : Z).

  Hypothesis Hra : getr R 1%bv = Z_to_bv 64 ret.
  Hypothesis Hret : ret_ok (Z_to_bv 64 ret).
  Hypothesis Hretr : 0 <= ret < 2 ^ 64.
  Hypothesis Hsp : getr R 2%bv = Z_to_bv 64 sp.
  Hypothesis Ha0 : getr R 10%bv = Z_to_bv 64 (sp + 368).
  Hypothesis Ha1 : getr R 11%bv = Z_to_bv 64 (sp + 848).
  Hypothesis Ha2 : getr R 12%bv = Z_to_bv 64 sp.
  Hypothesis Ha3 : getr R 13%bv = Z_to_bv 64 (sp + 96).
  Hypothesis Ha4 : getr R 14%bv = Z_to_bv 64 (sp + 264).
  Hypothesis Hsplo : 2 ^ 32 <= sp - 608.
  Hypothesis Hsphi : sp + 852 < 2 ^ 47.
  Hypothesis Hal : sp mod 16 = 0.
  Hypothesis HD : mdef M (sp - 608) 1460.
  Hypothesis Fap : fld SEGS M sp 8 (sp + 720).
  Hypothesis Fv : fld SEGS M (sp + 720) 8 v.
  Hypothesis Hv : 0 <= v < 2 ^ 64.
  Hypothesis F0 : fld SEGS M (sp + 848) 1 37.
  Hypothesis F1 : fld SEGS M (sp + 849) 1 108.
  Hypothesis F2 : fld SEGS M (sp + 850) 1 conv.
  Hypothesis F3 : fld SEGS M (sp + 851) 1 0.
  Hypothesis Hconv : conv = 117 \/ conv = 100 \/ conv = 120.
  Hypothesis Fflags : fld SEGS M (sp + 368) 4 0.
  Hypothesis Fwend : fld SEGS M (sp + 368 + 32) 8 (sp + 96).
  Hypothesis Fwpos : fld SEGS M (sp + 368 + 40) 8 (sp + 16).
  Hypothesis Flbf : fld SEGS M (sp + 368 + 144) 4 (2 ^ 32 - 1).
  Hypothesis ROC : ro_clear Ly.L M.
  Hypothesis RRC : relro_clear M.
  Hypothesis FCAN : fld SEGS M A_CANARY 8 rr_canary.

  Let pcs := sp - 544.

  Record pcframe (Mx : mem) : Prop := PCF {
    pf_sv : slots SEGS Mx sp [Z_to_bv 64 ret; getr R 8%bv; getr R 9%bv; getr R 18%bv; getr R 19%bv; getr R 20%bv; getr R 21%bv;
                             getr R 22%bv; getr R 23%bv; getr R 24%bv; getr R 25%bv; getr R 26%bv; getr R 27%bv];
    pf_can : fld SEGS Mx (pcs + 432) 8 rr_canary;
    pf_got : fld SEGS Mx (pcs + 96) 8 A_CANARY;
    pf_40 : fld SEGS Mx (pcs + 40) 8 MAGIC10_32;
    pf_48 : fld SEGS Mx (pcs + 48) 8 0xfffffffffffeffff;
    pf_72 : fld SEGS Mx (pcs + 72) 8 sp;
    pf_80 : fld SEGS Mx (pcs + 80) 8 0x12889;
    pf_104 : fld SEGS Mx (pcs + 104) 8 0xccccccc }.
  Definition pcconst (a : Z) : Prop := zwin (pcs + 40) (pcs + 88) a \/ zwin (pcs + 96) (pcs + 112) a \/ zwin (pcs + 432) sp a.
  Lemma pcframe_agree : forall Mx My, pcframe Mx -> agree_on pcconst Mx My -> pcframe My.
Proof using RRND R sp ret Hsplo Hsphi.
